frappe.ui.form.on("Project", {
    refresh: function(frm) {

        // 1. Hide standard sidebar Assign To
        $(".form-assignments").hide();

        // 2. Show custom field only for Administrator / Project Admin
        if (
            frappe.user_roles.includes("Project Admin") ||
            frappe.user === "Administrator"
        ) {
            frm.set_df_property("custom_assign_project_user", "hidden", 0);
        } else {
            frm.set_df_property("custom_assign_project_user", "hidden", 1);
        }

        // 3. When Projects Manager creates a NEW Project,
        // automatically assign the Project to themselves
        if (
            frm.is_new() &&
            frappe.user_roles.includes("Projects Manager") &&
            !frm.doc.custom_assign_project_user
        ) {
            frm.set_value(
                "custom_assign_project_user",
                frappe.session.user
            );
        }

        // 4. Filter custom field to show only Projects User (or Projects Manager for Project Admin)
        let target_role = "Projects User";
        if (frappe.user_roles.includes("Project Admin")) {
            target_role = "Projects Manager";
        }

        let args = { role: target_role };
        if (frappe.user_roles.includes("Project Admin")) {
            args.exclude_role = "Project Admin";
        }

        frappe.call({
            method: 'client_customization.api.get_users_by_role',
            args: args,
            callback: function(r) {
                let valid_users = r.message || [];
                if (valid_users.length === 0) valid_users = ["---"];

                frm.set_query(
                    "custom_assign_project_user",
                    function() {
                        return {
                            query: "client_customization.api.project_assign_user_query",
                            filters: {
                                "name": ["in", valid_users],
                                "enabled": 1,
                                "user_type": "System User"
                            }
                        };
                    }
                );
            }
        });
    },

    after_save: function(frm) {
        // 5. Create ToDo assignment
        if (frm.doc.custom_assign_project_user) {
            frappe.call({
                method: "frappe.desk.form.assign_to.add",
                args: {
                    doctype: frm.doc.doctype,
                    name: frm.doc.name,
                    assign_to: [ frm.doc.custom_assign_project_user ],
                    description: __("Project assigned via Manager form selector."),
                    priority: "Medium"
                },
                callback: function(r) {
                    if (!r.exc && !r.message) {
                        frappe.show_alert({
                            message: __("Successfully assigned to {0}", [frm.doc.custom_assign_project_user]),
                            indicator: "green"
                        });
                    }
                }
            });
        }
    }
});

frappe.ui.form.on('Task', {
    onload: function(frm) {
        frm.trigger('set_project_and_task_filters');
    },
    custom_assign_employee: function(frm) {
        frm.trigger('set_project_and_task_filters');
    },
    custom_employee_group: function(frm) {
        frm.trigger('set_project_and_task_filters');
    },
    set_project_and_task_filters: function(frm) {
        // Scenario 1: Particular Employee is selected
        if (frm.doc.custom_assign_employee) {
            frappe.db.get_value('Employee', frm.doc.custom_assign_employee, 'user_id', function(r) {
                if (r && r.user_id) {
                    apply_filters([r.user_id]);
                } else {
                    apply_filters(["No User Found"]);
                }
            });
        } 
        // Scenario 2: Only Employee Group is selected
        else if (frm.doc.custom_employee_group) {
            frappe.call({
                method: 'get_employee_groups_for_current_user',
                args: {
                    employee_group: frm.doc.custom_employee_group
                },
                callback: function(r) {
                    if (r && r.message && r.message.group_employees) {
                        let employees = r.message.group_employees;
                        if (employees.length > 0) {
                            frappe.db.get_list('Employee', {
                                filters: { name: ['in', employees] },
                                fields: ['user_id']
                            }).then(emp_records => {
                                let user_ids = emp_records.map(e => e.user_id).filter(u => u);
                                if (user_ids.length > 0) {
                                    apply_filters(user_ids);
                                } else {
                                    apply_filters(["No Users Found For Group"]);
                                }
                            });
                        } else {
                            apply_filters(["No Employees In Group"]);
                        }
                    } else {
                        apply_filters(["Error Fetching Group"]);
                    }
                }
            });
        }
        // Scenario 3: Neither is selected
        else {
            apply_filters([frappe.session.user]);
        }

        function apply_filters(target_users_array) {
            // Fetch Projects
            frappe.db.get_list('ToDo', {
                filters: { 'reference_type': 'Project', 'allocated_to': ['in', target_users_array], 'status': 'Open' },
                fields: ['reference_name']
            }).then(project_records => {
                let assigned_projects = project_records.map(row => row.reference_name);
                if (assigned_projects.length === 0) assigned_projects = ["No Assigned Projects Found"];
                frm.set_query('project', function() {
                    return { filters: [['Project', 'name', 'in', assigned_projects]] };
                });
            });

            // Fetch Tasks
            frappe.db.get_list('ToDo', {
                filters: { 'reference_type': 'Task', 'allocated_to': ['in', target_users_array], 'status': 'Open' },
                fields: ['reference_name']
            }).then(task_records => {
                let assigned_tasks = task_records.map(row => row.reference_name);
                if (assigned_tasks.length === 0) assigned_tasks = ["No Assigned Tasks Found"];

                // Set filter for parent_task
                frm.set_query('parent_task', function() {
                    return { filters: [['Task', 'name', 'in', assigned_tasks]] };
                });

                // If they have a custom task field, this will catch it
                if (frm.fields_dict.task) {
                    frm.set_query('task', function() {
                        return { filters: [['Task', 'name', 'in', assigned_tasks]] };
                    });
                }

                // Filter task in depends_on child table if it exists
                frm.set_query('task', 'depends_on', function() {
                    return { filters: [['Task', 'name', 'in', assigned_tasks]] };
                });
            });
        }
    }
});

frappe.ui.form.on('Task', {

    before_save: function(frm) {

        // If confirmation was already given, allow the save
        if (frm._employee_assignment_confirmed) {
            frm._employee_assignment_confirmed = false;
            return;
        }

        // Only ask confirmation when Employee is selected
        if (frm.doc.custom_assign_employee) {

            // Stop the current save
            frappe.validated = false;

            frappe.confirm(
                'Are you sure you want to assign Employee "' +
                frm.doc.custom_assign_employee +
                '" to this Task "' +
                frm.doc.subject +
                '"?',

                function() {

                    // YES
                    frm._employee_assignment_confirmed = true;

                    // Save the Task again
                    frm.save();
                },

                function() {

                    // NO
                    frappe.msgprint(
                        'Task was not saved. Please review the assigned Employee.'
                    );
                }
            );
        }
    }
});

frappe.ui.form.on('Task', {

    setup: function(frm) {

        // =================================================
        // EMPLOYEE GROUP FILTER
        // =================================================

        frm.set_query('custom_employee_group', function() {

            return {
                filters: {
                    name: ['in', []]
                }
            };

        });


        // =================================================
        // LOAD EMPLOYEE GROUPS
        // =================================================

        frappe.call({
            method: 'get_employee_groups_for_current_user',

            callback: function(r) {

                if (!r.message) {
                    return;
                }

                let employee_groups = r.message.employee_groups || [];

                console.log(
                    'Employee Groups:',
                    employee_groups
                );

                frm.set_query('custom_employee_group', function() {

                    return {
                        filters: {
                            name: ['in', employee_groups]
                        }
                    };

                });

            }
        });


        // =================================================
        // EMPLOYEE FILTER
        // =================================================

        frm.set_query('custom_assign_employee', function() {

            // If no Employee Group selected
            // show all Employees
            // if (!frm.doc.custom_employee_group) {

            //     return {
            //         filters: {
            //             status: 'Active'
            //         }
            //     };

            // }

            // Employee Group selected
            // get employees belonging to that group

            return {
                filters: {
                    status: 'Active'
                }
            };

        });

    },


    // =====================================================
    // WHEN EMPLOYEE GROUP CHANGES
    // =====================================================

    // =====================================================
// WHEN EMPLOYEE GROUP CHANGES
// =====================================================

custom_employee_group: function(frm) {

    // Clear previously selected employee
    frm.set_value('custom_assign_employee', '');

    // No group selected
    if (!frm.doc.custom_employee_group) {

        // Show NO employees when group is cleared
        frm.set_query('custom_assign_employee', function() {

            return {
                filters: {
                    name: ['in', []]
                }
            };

        });

        frm.refresh_field('custom_assign_employee');

        return;
    }


    // Get employees from selected Employee Group
    frappe.call({
        method: 'get_employee_groups_for_current_user',

        args: {
            employee_group: frm.doc.custom_employee_group
        },

        callback: function(r) {

            if (!r.message) {
                return;
            }

            let employees = r.message.group_employees || [];

            console.log(
                'Employees in selected group:',
                employees
            );

            frm.set_query(
                'custom_assign_employee',
                function() {

                    return {
                        query: 'client_customization.api.employee_group_query',
                        filters: {
                            name: ['in', employees],
                            status: 'Active'
                        }
                    };

                }
            );

            // Refresh the field so the new filter is applied
            frm.refresh_field('custom_assign_employee');

        }
    });

}

});
